                      if row[0] != bg and all(v == row[0] for v in row)), None)
    if guide_row is None:
        return [row[:] for row in grid]
    guide = grid[guide_row][0]
    obj = next((v for v in counts if v != bg and v != guide), None)
    if obj is None:
        return [row[:] for row in grid]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj]
    top = min(r for r, _ in cells)
    bottom = max(r for r, _ in cells)
    out = [row[:] for row in grid]
