def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    guide_row = next((r for r, row in enumerate(grid)
                      if row[0] != bg and all(v == row[0] for v in row)), None)
    if guide_row is None:
        return [row[:] for row in grid]
    guide = grid[guide_row][0]
    obj = next((v for v in counts if v != bg and v != guide), None)
    if obj is None:
        return [row[:] for row in grid]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj]
    top = min(r for r, _ in cells)
    bottom = max(r for r, _ in cells)
    out = [row[:] for row in grid]
    # Move the figure against the bar, keeping it on its original side.
    if bottom < guide_row:
        shift = guide_row - 1 - bottom
        marker_row = top + shift - 1
        dr = shift
    elif top > guide_row:
        shift = top - guide_row - 1
        marker_row = bottom - shift + 1
        dr = -shift
    else:
        return out
    for r, c in cells:
        out[r][c] = bg
    for r, c in cells:
        out[r + dr][c] = obj
    if 0 <= marker_row < h:
        out[marker_row] = [8] * w
    return out
